"""Record real fixed12 primary evidence and revalidated live pending jobs."""
from pathlib import Path
import base64,copy,hashlib,json
ROOT=Path.cwd();MAIN=ROOT/'outputs/stem_component12_20261011_v1';REF=ROOT/'outputs/native_stem_scratch12_20261011_v3'
QUEUE=ROOT/'outputs/stem_component_queue_pulse_20261011_v2';FULL=ROOT/'outputs/original_stem12_20261011_v1'
CURVES=ROOT/'outputs/stem_curves_20261011_v1';JOINT=ROOT/'outputs/stem_primary_joint_analysis12_20261011_v1'
read=lambda p:json.loads(Path(p).read_bytes())
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(p,x):
    with Path(p).open('x',encoding='utf8') as f:json.dump(x,f,ensure_ascii=False,indent=2,allow_nan=False)
inputs=json.loads(r'''{"reference":{"1":{"base64":"","expected_sha256":"8be3a1ec0713d2ac7ce765ba1316b3473a7f52b95212449bd3fbb348aba32e9f","expected_bytes":3038},"2":{"base64":"","expected_sha256":"5f126f4c8fa806925ab9604450c0ba31dce68fe7b99727415eb3a9625761cf72","expected_bytes":3045}},"queue":{"1":{"base64":"","sha256":"4aa8ee83d516601cda157b528c7bb7a19514d64f100f269bad6a35ba6b8ea74a","bytes":1469},"2":{"base64":"","sha256":"003d6342d710eb1f17cbfbae5d1e43992314ecfd04d912a27218b93ac9f1fe7f","bytes":2876}}}''')
refs={};queues={};transport={}
for kind in ('reference','queue'):
    for seed in (1,2):
        d=inputs[kind][str(seed)];b=base64.b64decode(d['base64'],validate=True)
        size=d.get('expected_bytes',d.get('bytes'));digest=d.get('expected_sha256',d.get('sha256'))
        assert len(b)==size and hashlib.sha256(b).hexdigest()==digest
        o=json.loads(b);assert o['seed']==seed
        (refs if kind=='reference' else queues)[str(seed)]=o
        if kind=='reference':
            assert o['code_sha256_verified'] and not o['failures']
            assert o['completed_epochs']==o['latest_metrics']['epoch']+1
            assert all(v['same_live'] for v in o['processes'].values())
        else:
            assert o['code_SHA_verified'] and o['component_SHA_verified'] and not o['failure']
        transport[kind+str(seed)]={'bytes':size,'sha256':digest}
snapfile=MAIN/'training_observation_v26.json';snap=read(snapfile)
assert sha(snapfile)==read(MAIN/'training_observation_v26_transport_verification.json')['verified_snapshot_sha256']
old=read(MAIN/'training_observation_v25.json')
for seed in (1,2):
    assert not snap[f'seed{seed}']['errors']
    for arm,job in old[f'seed{seed}']['jobs'].items():
        new=snap[f'seed{seed}']['jobs'][arm]['metrics']
        assert new[:len(job['metrics'])]==job['metrics']
    full=snap[f'seed{seed}']['jobs']['original_stem']
    assert len(full['metrics'])==12 and not any(v['same_live'] for v in full['processes'])
    assert full['records']['training_completion.json']['status']=='NATIVE_FIT_FINISHED_EXACT12'
joint=read(JOINT/'report.json')
assert joint['status']=='ANALYZED_BOTH_PRIMARY_FIXED12_JOINT_PARTITION_REPLAY_PENDING'
for name,h in read(JOINT/'manifest.json')['files'].items():assert sha(JOINT/name)==h
assert not joint['saved_EMA_independent_replay_verified'] and not joint['causal_root_proven']
pairs=[]
for seed in (1,2):
    r=refs[str(seed)];e=r['completed_epochs'];v=snap[f'seed{seed}']['jobs']['original_stem']['metrics'][e-1]['test_coco_eval_bbox'];n=r['latest_metrics']['test_coco_eval_bbox']
    pairs.append(dict(seed=seed,epoch=e,enhanced_AP=100*v[0],random_native_AP=100*n[0],delta_AP_pp=100*(v[0]-n[0]),
      enhanced_APs=100*v[3],random_native_APs=100*n[3],delta_APs_pp=100*(v[3]-n[3])))
