write(REF/'compact_transport_v10.json',{str(s):transport['reference'+str(s)] for s in (1,2)})
write(QUEUE/'remote_transport_v4.json',dict(status='PASS_BOTH_BYTE_LENGTH_SHA256',records={str(s):transport['queue'+str(s)] for s in (1,2)}))
write(MAIN/'same_epoch_random_native_comparison_v7.json',dict(status='ANALYZED_DESCRIPTIVE_SAME_EPOCH_PER_SEED6_AND7',
 current_S_pairs=pairs,full_snapshot_sha256=sha(snapfile),random_native_observation_sha256=sha(REF/'compact_observation_v10.json'),
 all_seeds_preserved=True,fixed12_efficacy_established=False,root_cause_established=False,new_model_forwards=0,new_optimizer_updates=0))
